-- Resources content for Bookings' slice 3, projects (CLAUDE.md, "Resources
-- stay in step with the code"). Content only; the schema is
-- 20261006120000_bookings_projects.sql. Two new guides — the Requests list
-- and a request's page, and the Dashboard — and the release note.

select private.rc_release_guide(
  p_slug => 'bookings-requests',
  p_tool_key => 'bookings',
  p_title => 'Requests and estimates',
  p_summary => 'A request through five stages: how it is priced, the estimate, planning and holding dates, airtime commitments, and closing a request.',
  p_screen_keys => array['bookings.requests', 'bookings.project'],
  p_sort_order => 20,
  p_version_note => 'Slice 3: requests, estimates, dates and airtime commitments',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Requests","marks":[{"type":"bold"}]},{"type":"text","text":" tab lists every request for university production work. A request moves through five stages — Request, Estimate, Booked, Delivered, Settled — and can be deferred, declined or withdrawn at any point before delivery. Production staff enter a request with "},{"type":"text","text":"+ New request","marks":[{"type":"bold"}]},{"type":"text","text":", naming the partner on file or a new one, what is asked for (production, airtime or both), the event dates and the contact."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"How a request is priced"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nobody picks a price. The treatment is derived from facts on the request and the estimate says why: a partner outside the university is priced "},{"type":"text","text":"external","marks":[{"type":"bold"}]},{"type":"text","text":"; work recorded as strategic or applied-learning is priced "},{"type":"text","text":"strategic","marks":[{"type":"bold"}]},{"type":"text","text":" when the term's reserve covers its professional hours; everything else is "},{"type":"text","text":"incremental","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Record the strategic judgment on the request's scope (Edit in the Scope panel). "},{"type":"text","text":"Change how it is priced","marks":[{"type":"bold"}]},{"type":"text","text":" lets production staff set a treatment by hand with a reason; pricing a request strategic against its derived treatment draws the reserve and is the Executive Director's call. Every change is recorded."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Rates come from the rate card recorded for estimates on the Rates tab, and the estimate keeps the version it was first priced on. While no version is adopted every figure is provisional."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The estimate"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Add a line","marks":[{"type":"bold"}]},{"type":"text","text":" adds a service package (a studio half-day, a basic webcast, a field day), labor hours beyond a package, or a direct expense at cost. A package line carries the package's hours per labor class, which is what the dates draw on."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Plan a date","marks":[{"type":"bold"}]},{"type":"text","text":" adds each window the work needs — pool, date, window and the hours it takes from each class. A planned date takes nothing yet; the page runs the booking rule for every planned date and reads the result as one line, with "},{"type":"text","text":"show the check","marks":[{"type":"bold"}]},{"type":"text","text":" listing any date that would be refused and the nearest open windows."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Send the estimate","marks":[{"type":"bold"}]},{"type":"text","text":" holds every planned date tentatively for 14 days. The holds are placed all or none: a date the rule refuses stops the send and names the reason. Tentative holds count as taken for every other request."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"When the partner approves, "},{"type":"text","text":"Partner approved — book it","marks":[{"type":"bold"}]},{"type":"text","text":" confirms the holds and the request is Booked. An estimate that lapses can be sent again, which re-checks its dates. "},{"type":"text","text":"Mark delivered","marks":[{"type":"bold"}]},{"type":"text","text":" once the work is done."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Airtime"}]},{"type":"paragraph","content":[{"type":"text","text":"A request for airtime records a commitment — airings a week, length, dates, and whether it is contributed from the term's envelope or paid. The page compares contributed commitments across requests with the envelope. The avails themselves are placed in Traffic (a message, as copy on a bonus or paid line) or On Air (a recurring feature, pinned on the clock), never here; once placed, paste the contract's or the pin's id so the request can show what was actually scheduled."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Closing a request"}]},{"type":"paragraph","content":[{"type":"text","text":"Close the request","marks":[{"type":"bold"}]},{"type":"text","text":" defers, declines or withdraws it with a reason. Every hold is released and the stage it reached is kept. Declining an outside partner's request for capacity can record the estimate's margin as foregone for the term report. A closed request can be reopened; its dates must be planned again."}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'bookings-dashboard',
  p_tool_key => 'bookings',
  p_title => 'The dashboard',
  p_summary => 'The term''s capacity bar, the airtime envelope in one line, what needs your action, this week''s dates, and the stage tiles.',
  p_screen_keys => array['bookings.dashboard'],
  p_sort_order => 5,
  p_version_note => 'Slice 3',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Dashboard","marks":[{"type":"bold"}]},{"type":"text","text":" is where Bookings opens. It shows the active term's production capacity as one bar — strategic bookings against the reserve, the reserve still to preserve, incremental and external bookings, hours held for WUWF's own work, and what is open — and the airtime envelope in one line: contributed minutes a week, how much is committed to requests, and what is left."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Needs your action","marks":[{"type":"bold"}]},{"type":"text","text":" lists what each open request is waiting on, filtered to your roles: a request without an estimate, an estimate about to expire or expired, a booked event that has passed and needs marking delivered, and a request that needs editorial review. A member with no role sees every item."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"This week","marks":[{"type":"bold"}]},{"type":"text","text":" lists the partner dates held or confirmed this week, linked to their requests."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The four tiles count open requests by stage and link to the Requests list filtered to each."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Nothing shows until the Director of Operations has activated a term plan on the Calendar tab."}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-06-bookings-projects',
  p_tool_key => 'bookings',
  p_released_on => '2026-10-06',
  p_title => 'Bookings: requests, estimates and the dashboard',
  p_guide_slugs => array['bookings-requests', 'bookings-dashboard'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Bookings now takes requests. A new Requests tab lists every request for university production work through five stages — request, estimate, booked, delivered, settled — with a page for each: an estimate whose treatment is derived from the partner, the strategic judgment and the term's reserve, lines priced from the rate card recorded for estimates, dates planned and checked against the calendar before the estimate is sent, tentative holds that count as taken for 14 days and are confirmed when the partner approves, airtime commitments checked against the term's envelope, and a reason for every deferral, decline or withdrawal. A new Dashboard opens the tool with the term's capacity bar, the airtime envelope, what needs your action by role, this week's dates and the stage tiles. Partners are named on a request for now; their own tab and agreements follow."}]}]}$body$
);
